package com.leotechnologies.tests;

import com.leotechnologies.tests.core.DashboardText;

import java.io.IOException;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.nio.file.DirectoryStream;
import java.nio.file.Files;
import java.nio.file.InvalidPathException;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.time.ZoneOffset;
import java.time.ZonedDateTime;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;

/**
 * The suite's runs over time: at the end of every run, its line is added to dashboard/history.tsv and
 * dashboard.html, at the suite's top beside AUDIT.html, is written again from it, the newest runs first. A run with
 * failures also gets a page of its own, dashboard/reports/&lt;id&gt;.html: each failed test and why, in one line.
 * Written
 * by the suite itself; commit dashboard.html and dashboard/ to keep the history (target/ stays out of git). A line's
 * kind
 * says what ran: "tests" here; "load" for a load run, which adds its line and its page the same way. Every text a run
 * gives is masked before it is written (core/DashboardText): the suite's own accounts, and every secret's shape.
 */
public final class Dashboard {
    /** The page, its history, and the failed runs' pages. */
    public static final Path PAGE = Path.of("dashboard.html");
    public static final Path HISTORY = Path.of("dashboard", "history.tsv");
    public static final Path REPORTS = Path.of("dashboard", "reports");
    /** Where a failed test's evidence is kept (BaseTest): a folder of its own, right inside it. */
    private static final Path FAILURES = Path.of("target", "failures");

    private static final String TOP =
            "<!doctype html>\n<html lang=en><meta charset=utf-8><meta http-equiv=\"Content-Security-Policy\" content="
            + "\"default-src 'none'; style-src 'unsafe-inline'; img-src 'self' data:\">\n<!-- EDIT RULES: the suite's "
            + "own run code writes this page again at the end of every run, from dashboard/history.tsv; Suite Builder "
            + "writes it only where there is none. Commit it, with dashboard/, to keep the history. -->"
            + "\n<title>Dashboard: the suite's runs</title><style>:root{color-scheme:dark}"
            + "\nbody{background:#07030f;color:#d1f7ff;font:14px/1.5 ui-monospace,SFMono-Regular,Menlo,Consolas,"
            + "monospace;margin:0 auto;max-width:76em;padding:1.5em 1em;border-top:3px solid #ff2a6d}"
            + "\nh1{color:#05d9e8;font-size:1.5em;letter-spacing:.06em;text-transform:uppercase;text-shadow:0 0 8px "
            + "#05d9e880;border-bottom:1px solid #783cc8;padding-bottom:.3em}\na{color:#05d9e8}"
            + "\ntable{border-collapse:collapse;width:100%;background:#100620;border:1px solid #783cc8}"
            + "\nth{color:#f9f002;text-align:left;padding:.4em .6em;border-bottom:2px solid "
            + "#ff2a6d;font-weight:normal;letter-spacing:.04em}\ntd{padding:.35em .6em;border-bottom:1px solid "
            + "#340e52;vertical-align:top;overflow-wrap:anywhere}\ntr.passed td:first-child{box-shadow:inset 3px 0 "
            + "#05d9e8}\ntr.passed td:nth-child(3){color:#05d9e8}\ntr.failed td:first-child{box-shadow:inset 3px 0 "
            + "#ff2a6d}\ntr.failed td,tr.failed a{color:#ff2a6d}\ntr.refused td:first-child{box-shadow:inset 3px 0 "
            + "#ffc478}\ntr.refused td,tr.refused a{color:#ffc478}"
            + "\nh2{color:#f9f002;font-size:1.1em;font-weight:normal;letter-spacing:.04em}"
            + "\n.older{color:#ffc478}</style>\n<h1>The suite's runs</h1>\n<p>The newest 100 runs, newest first: when "
            + "it ran, what ran, and how it went. A run with failures has a page of its own in dashboard/reports/; a "
            + "run that passed is its line. A run the site's infrastructure refused (a firewall or bot check kept this "
            + "computer out) is neither: its tests were not run, and its finding has a page there too. The site's "
            + "audit is AUDIT.html, beside this page.</p>\n";
    private static final String HEAD =
            "<!doctype html>\n<html lang=en><meta charset=utf-8><meta http-equiv=\"Content-Security-Policy\" content="
            + "\"default-src 'none'; style-src 'unsafe-inline'; img-src 'self' data:\">";
    private static final String TABLE = "<table><tr><th>When (UTC)<th>What ran<th>Result<th>Counts<th>Failures";
    private static final String STYLE =
            ":root{color-scheme:dark}\nbody{background:#07030f;color:#d1f7ff;font:14px/1.5 ui-monospace,SFMono-Regular,"
            + "Menlo,Consolas,monospace;margin:0 auto;max-width:76em;padding:1.5em 1em;border-top:3px solid #ff2a6d}"
            + "\nh1{color:#05d9e8;font-size:1.5em;letter-spacing:.06em;text-transform:uppercase;text-shadow:0 0 8px "
            + "#05d9e880;border-bottom:1px solid #783cc8;padding-bottom:.3em}\na{color:#05d9e8}"
            + "\ntable{border-collapse:collapse;width:100%;background:#100620;border:1px solid #783cc8}"
            + "\nth{color:#f9f002;text-align:left;padding:.4em .6em;border-bottom:2px solid "
            + "#ff2a6d;font-weight:normal;letter-spacing:.04em}\ntd{padding:.35em .6em;border-bottom:1px solid "
            + "#340e52;vertical-align:top;overflow-wrap:anywhere}\ntr.passed td:first-child{box-shadow:inset 3px 0 "
            + "#05d9e8}\ntr.passed td:nth-child(3){color:#05d9e8}\ntr.failed td:first-child{box-shadow:inset 3px 0 "
            + "#ff2a6d}\ntr.failed td,tr.failed a{color:#ff2a6d}\ntr.refused td:first-child{box-shadow:inset 3px 0 "
            + "#ffc478}\ntr.refused td,tr.refused a{color:#ffc478}"
            + "\nh2{color:#f9f002;font-size:1.1em;font-weight:normal;letter-spacing:.04em}\n.older{color:#ffc478}";
    private static final String OLDER_LEAD = "<p class=older>Older runs, not shown here: ";
    private static final String OLDER_TAIL =
            ", in dashboard/history.tsv; a failed one's page stays in dashboard/reports/.</p>\n";
    private static final String HISTORY_HEAD =
            "# The suite's runs, a line each, oldest first; dashboard.html is made from it. kind: tests (a load run: "
            + "load). selection: which tests ran.\nwhen\tkind\tid\tresult\tpassed\tfailed\tskipped\tpage\tnote"
            + "\tselection\n";
    private static final String EVIDENCE =
            "<p>The run's own evidence stays on the computer that ran it, until its next run there: <a href="
            + "\"../../target/report.html\">target/report.html</a>, and each failed test's folder in <a href="
            + "\"../../target/failures/\">target/failures/</a>.</p>\n";
    /** A failure's why, at most: its first line, cut here; the masks read at most READ_MAX of it. */
    private static final int WHY_MAX = 300;
    private static final int READ_MAX = 1000;
    /** The runs the page shows, the newest; the rest stay in the history, counted. */
    private static final int SHOWN = 100;
    /** The crawled site's folder in Suite Builder's account store. */
    private static final String STORE_SITE = "leotechnologies.com";
    /** How a run's selection is said. */
    private static final String ALL = "all tests";
    private static final Set<String> NAMED = Set.of("smoke", "audit");
    private static final String FAMILY = "family ";
    private static final String TEST = "test ";
    /**
     * A run the site's infrastructure refused: its result, its link's words, its page's title and heading, and how the
     * run's end says it.
     */
    private static final String REFUSED = "refused";
    private static final String REFUSED_LINK = "the finding";
    private static final String REFUSED_TITLE = "Refused run ";
    private static final String REFUSED_HEADING = "A run the site's infrastructure refused, ";
    private static final String REFUSED_SAID = "this run's finding: ";

    private Dashboard() {
    }

    /**
     * Adds a run to the history and writes the page again; a failed run's page too. Never fails the run: a file that
     * cannot be written is said, and the run goes on. The history's line first, so a run whose page cannot be written
     * still has its line.
     *
     * @param kind what ran: "tests", or "load"
     * @param selection which tests the run chose (selection())
     * @param failures each failed test: its name, why it failed, and its evidence folder from the suite's top ("" when
     * none)
     */
    public static synchronized void record(String kind, String selection, int passed, int failed, int skipped,
            boolean failedRun, String note, List<String[]> failures) {
        record(kind, selection, passed, failed, skipped, failedRun, note, failures, List.of());
    }

    /**
     * As above, with the finding of a run the site's infrastructure refused (core/Refused.finding(): a line each,
     * the first its name; empty for none). A refused run with no failure is neither passed nor failed: its result
     * says refused, its note the finding's name, and its page holds the finding; a failed run that was refused too
     * holds it on its page.
     */
    public static synchronized void record(String kind, String selection, int passed, int failed, int skipped,
            boolean failedRun, String note, List<String[]> failures, List<String> finding) {
        List<String> accounts = accounts();
        List<String[]> history;
        try {
            history = history();
        } catch (IOException e) {
            said(HISTORY, e);
            return;
        }
        Set<String> ids = new HashSet<>();
        history.forEach(r -> ids.add(r[2]));
        ZonedDateTime now = ZonedDateTime.now(ZoneOffset.UTC).withNano(0);
        String stamp = now.format(DateTimeFormatter.ofPattern("yyyy-MM-dd_HHmmss", Locale.ROOT));
        String id = stamp;
        for (int n = 2; ids.contains(id); n++) id = stamp + "-" + n;
        String when = now.format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss", Locale.ROOT));
        boolean refused = !finding.isEmpty();
        String page = failedRun || refused ? "dashboard/reports/" + id + ".html" : "";
        String noted = refused ? finding.get(0) + "." + (note == null || note.isBlank() ? "" : " " + note) : note;
        String[] line = {when, field(kind), id, failedRun ? "failed" : refused ? REFUSED : "passed",
                String.valueOf(passed), String.valueOf(failed), String.valueOf(skipped), page,
            field(why(noted, accounts)), field(why(selection, accounts))};
        try {
            Files.createDirectories(HISTORY.getParent());
            if (!Files.exists(HISTORY)) write(HISTORY, HISTORY_HEAD);
            Files.write(HISTORY, bytes(String.join("\t", line) + "\n"), StandardOpenOption.APPEND);
        } catch (IOException e) {
            said(HISTORY, e);
            return;
        }
        history.add(line);
        if (!page.isEmpty()) {
            try {
                Files.createDirectories(REPORTS);
                write(REPORTS.resolve(id + ".html"), failurePage(line, failures, finding, accounts));
            } catch (IOException e) {
                said(REPORTS, e);
            }
        }
        try {
            write(PAGE, page(history));
            System.out.println("The suite's dashboard: " + PAGE.toAbsolutePath().toUri()
                    + (failedRun ? " (this run's failures: " + page + ")" : refused ? " (" + REFUSED_SAID + page
                    + ")" : ""));
        } catch (IOException e) {
            said(PAGE, e);
        }
    }

    /**
     * Which tests this run chose, as Maven gave it: -Dgroups (a family: smoke and audit by name), -Dtest (a test), or
     * neither (all tests).
     */
    public static String selection() {
        String groups = System.getProperty("groups", "").strip();
        String test = System.getProperty("test", "").strip();
        if (!groups.isEmpty()) return NAMED.contains(groups) ? groups : FAMILY + groups;
        return test.isEmpty() ? ALL : TEST + test;
    }

    /**
     * A failed test's evidence folder, from the suite's top, as a link ("" when there is none): the folder named by the
     * test's
     * class, only when it is right inside target/failures/ (a name is the site's words: never a way out of it), its
     * name
     * percent-encoded in the link.
     */
    public static String evidence(String test) {
        int cut = test.indexOf(" > ");
        try {
            Path folder = FAILURES.resolve(cut < 0 ? test : test.substring(0, cut)).normalize();
            if (!FAILURES.equals(folder.getParent()) || folder.getFileName() == null
                    || !Files.isDirectory(folder)) return "";
            return "target/failures/" + URLEncoder.encode(folder.getFileName().toString(), StandardCharsets.UTF_8)
                    .replace("+", "%20") + "/";
        } catch (InvalidPathException e) {
            return "";
        }
    }

    /**
     * The history's runs, oldest first: each line of nine or ten fields; a line that is not one (a half line) is left
     * out.
     */
    private static List<String[]> history() throws IOException {
        List<String[]> runs = new ArrayList<>();
        if (!Files.exists(HISTORY)) return runs;
        String all = new String(Files.readAllBytes(HISTORY), StandardCharsets.UTF_8);
        for (int start = 0, end; start < all.length(); start = end + 1) {
            end = all.indexOf('\n', start);
            if (end < 0) end = all.length();
            String text = all.substring(start, end);
            if (text.endsWith("\r")) text = text.substring(0, text.length() - 1);
            List<String> r = new ArrayList<>();
            for (int from = 0, tab = 0; tab >= 0; from = tab + 1) {
                tab = text.indexOf('\t', from);
                r.add(tab < 0 ? text.substring(from) : text.substring(from, tab));
            }
            if (r.size() == 9) r.add("");
            if (!text.startsWith("#") && r.size() == 10 && !r.get(0).equals("when")) runs.add(r.toArray(new String[0]));
        }
        return runs;
    }

    /**
     * dashboard.html: the head, then a line a run, the newest SHOWN first, and how many older runs the history holds.
     */
    private static String page(List<String[]> history) {
        StringBuilder html = new StringBuilder(TOP).append(TABLE);
        int oldest = Math.max(0, history.size() - SHOWN);
        for (int i = history.size() - 1; i >= oldest; i--) {
            String[] r = history.get(i);
            String link = DashboardText.isReportPage(r[7]) ? "<a href=\"" + escape(r[7]) + "\">"
                    + (r[3].equals(REFUSED) ? REFUSED_LINK : "the failures") + "</a>" : "";
            html.append("\n<tr class=")
                    .append(r[3].equals("failed") ? "failed" : r[3].equals(REFUSED) ? REFUSED : "passed")
                    .append("><td>").append(escape(r[0])).append("<td>").append(escape(r[1]))
                    .append(r[9].isEmpty() ? "" : ": " + escape(r[9])).append("<td>").append(escape(r[3]))
                            .append("<td>").append(escape(counts(r))).append("<td>").append(link)
                    .append(r[8].isEmpty() ? "" : (link.isEmpty() ? "" : " ") + escape(r[8]));
        }
        html.append("\n</table>\n");
        if (oldest > 0) html.append(OLDER_LEAD).append(oldest).append(OLDER_TAIL);
        return html.toString();
    }

    /**
     * A failed or refused run's own page: what ran and how, the finding of a run the site's infrastructure refused (its
     * name
     * a heading, a paragraph a line), where its evidence is, and each failed test with why, one line each.
     */
    private static String failurePage(String[] r, List<String[]> failures, List<String> finding,
            List<String> accounts) {
        boolean refused = r[3].equals(REFUSED);
        StringBuilder html = new StringBuilder(HEAD).append("<title>").append(refused ? REFUSED_TITLE : "Failed run ")
                .append(escape(r[0])).append("</title><style>").append(STYLE)
                        .append("</style>\n<p><a href=\"../../dashboard.html\">Every run</a></p>\n<h1>")
                        .append(refused ? REFUSED_HEADING : "A failed run, ")
                .append(escape(r[0])).append(" UTC</h1>\n<p>").append(escape(r[1]))
                        .append(r[9].isEmpty() ? "" : ": " + escape(r[9])).append(", ").append(escape(counts(r)))
                        .append(".")
                .append(r[8].isEmpty() || !finding.isEmpty() ? "" : " " + escape(r[8])).append("</p>\n");
        for (int i = 0; i < finding.size(); i++) html.append(i == 0 ? "<h2>" : "<p>").append(escape(finding.get(i)))
                .append(i == 0 ? "</h2>\n" : "</p>\n");
        html.append(EVIDENCE);
        if (refused && failures.isEmpty()) return html.toString();
        html.append("<table><tr><th>Failed<th>Why");
        for (String[] f : failures) {
            String evidence = f[2].isEmpty() ? "" : " (<a href=\"../../" + escape(f[2]) + "\">evidence</a>)";
            html.append("\n<tr><td>").append(escape(why(f[0], accounts))).append("<td>")
                    .append(escape(why(f[1], accounts))).append(evidence);
        }
        return html.append("\n</table>\n").toString();
    }

    private static String counts(String[] r) {
        return r[4] + " passed, " + r[5] + " failed" + (r[6].equals("0") ? "" : ", " + r[6] + " skipped");
    }

    /** A text as one line, masked, WHY_MAX characters at most, cut between two characters, never inside one. */
    private static String why(String text, List<String> accounts) {
        String line = text == null ? "" : text.strip();
        for (char end : new char[] {'\n', '\r'}) if (line.indexOf(end) >= 0) line = line.substring(0,
                line.indexOf(end));
        line = DashboardText.masked(cut(line, READ_MAX), accounts);
        return line.codePointCount(0, line.length()) > WHY_MAX ? cut(line, WHY_MAX) + "..." : line;
    }

    /** The text's first `max` characters (code points: a pair of surrogates is one character, never split). */
    private static String cut(String text, int max) {
        return text.codePointCount(0, text.length()) <= max ? text : text.substring(0, text.offsetByCodePoints(0, max));
    }

    /**
     * The suite's own account values, which no line or page shows: the environment's SUITE_..._USERNAME and _PASSWORD,
     * every account file in secrets/, and the site's in Suite Builder's store (SUITE_BUILDER_SECRETS, or the dock's).
     */
    private static List<String> accounts() {
        List<String> values = new ArrayList<>();
        for (Map.Entry<String, String> e : System.getenv().entrySet()) {
            String name = e.getKey();
            if (name.startsWith("SUITE_") && (name.endsWith("_USERNAME") || name.endsWith("_PASSWORD"))) values.add(
                    e.getValue());
        }
        loginFiles(Path.of("secrets"), values);
        Path store = store();
        if (store != null) loginFiles(store.resolve(STORE_SITE), values);
        return values;
    }

    /** The values of each .login file in a folder: everything after the first colon of each line. */
    private static void loginFiles(Path folder, List<String> values) {
        if (!Files.isDirectory(folder)) return;
        try (DirectoryStream<Path> files = Files.newDirectoryStream(folder, "*.login")) {
            for (Path file : files) {
                for (String line : Files.readAllLines(file, StandardCharsets.UTF_8)) {
                    int colon = line.indexOf(':');
                    if (colon >= 0) values.add(line.substring(colon + 1));
                }
            }
        } catch (IOException | RuntimeException e) {
            // An account file that cannot be read signs nothing in, so no run's words hold it.
        }
    }

    /**
     * Suite Builder's account store: SUITE_BUILDER_SECRETS, else, docked, the folder the dock's DOCK.md names
     * (Accounts: ...).
     */
    private static Path store() {
        String set = System.getenv("SUITE_BUILDER_SECRETS");
        if (set != null && !set.isBlank()) return Path.of(set.strip());
        Path parent = Path.of("").toAbsolutePath().getParent();
        Path dock = parent == null ? null : parent.resolve("DOCK.md");
        if (dock == null || !Files.isRegularFile(dock)) return null;
        try {
            for (String line : Files.readAllLines(dock, StandardCharsets.UTF_8)) if (
                    line.startsWith("Accounts: ")) return Path.of(line.substring("Accounts: ".length()).strip());
        } catch (IOException | RuntimeException e) {
            return null;
        }
        return null;
    }

    /** A file written as UTF-8, a lone surrogate (a half character a test's name or a message may hold) as "?". */
    private static void write(Path file, String text) throws IOException {
        Files.write(file, bytes(text));
    }

    private static byte[] bytes(String text) {
        return text.getBytes(StandardCharsets.UTF_8);
    }

    private static void said(Path file, IOException e) {
        System.out.println("   note: could not write the suite's dashboard (" + file + "): " + e.getMessage());
    }

    /** A history field: no tab or line break of its own. */
    private static String field(String text) {
        return text == null ? "" : text.replace('\t', ' ').replace('\r', ' ').replace('\n', ' ').strip();
    }

    private static String escape(String text) {
        return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;").replace("\"", "&quot;")
                .replace("'", "&#39;");
    }
}
